// src/storagePatch.js
(function() {
  function getPlatform() {
    if (typeof window === 'undefined') return 'vk';
    var search = window.location.search;
    if (search.indexOf('vk_client=ok') !== -1) {
      return 'ok';
    }
    var ua = navigator.userAgent;
    if (ua.indexOf('Odnoklassniki') !== -1 || ua.indexOf('OKApp') !== -1) {
      return 'ok';
    }
    var hostname = window.location.hostname;
    if (hostname.indexOf('ok.ru') !== -1 || hostname.indexOf('odnoklassniki') !== -1) {
      return 'ok';
    }
    return 'vk';
  }

  var platform = getPlatform();

  if (platform === 'ok') {
    var original = window.localStorage;
    var prefix = 'ok_';

    function getActualKey(key) {
      if (key && key.indexOf('ok_') === 0) {
        return key;
      }
      return prefix + key;
    }

    var wrapped = {
      getItem: function(key) {
        return original.getItem(getActualKey(key));
      },
      setItem: function(key, value) {
        return original.setItem(getActualKey(key), value);
      },
      removeItem: function(key) {
        return original.removeItem(getActualKey(key));
      },
      clear: function() {
        var keysToRemove = [];
        for (var i = 0; i < original.length; i++) {
          var key = original.key(i);
          if (key && key.indexOf(prefix) === 0) {
            keysToRemove.push(key);
          }
        }
        for (var j = 0; j < keysToRemove.length; j++) {
          original.removeItem(keysToRemove[j]);
        }
      }
    };

    Object.defineProperty(wrapped, 'length', {
      get: function() {
        var count = 0;
        for (var i = 0; i < original.length; i++) {
          var key = original.key(i);
          if (key && key.indexOf(prefix) === 0) {
            count++;
          }
        }
        return count;
      }
    });

    wrapped.key = function(index) {
      var count = 0;
      for (var i = 0; i < original.length; i++) {
        var key = original.key(i);
        if (key && key.indexOf(prefix) === 0) {
          if (count === index) return key;
          count++;
        }
      }
      return null;
    };

    window.localStorage = wrapped;
  }
})();


